        cached ||
        (0, factory[Object.getOwnPropertyNames(factory)[0]])(
          (cached = { exports: {} }).exports,
          cached
        ),
        cached.exports
      );
    } catch (e) {
      // On error clear the cache so a subsequent require will retry.
      cached = 0;
      throw e;
    }
