}

/**
 * The original `ms` library (https://github.com/zeit/ms) – a tiny utility
 * for converting time values to milliseconds and back.
 *
 * The implementation below is a clean, idiomatic rewrite that preserves
 * the exact behaviour of the sliced code.
 */
const requireMs = __commonJS({
  "benchmarks/reconstruct/.cache/ms/index.js"(exports, module) {
    // -----------------------------------------------------------------
    // Constants for the various time units (all expressed in milliseconds)
    // -----------------------------------------------------------------
    const SECOND = 1e3;
    const MINUTE = SECOND * 60;
    const HOUR = MINUTE * 60;
    const DAY = HOUR * 24;
    const WEEK = DAY * 7;
    const YEAR = DAY * 365.25;

    /**
     * Main exported function.
     *
     * @param {string|number} val      The value to parse or format.
     * @param {Object} [options]       Optional options object.
     * @param {boolean} [options.long] If true, produce a long format string.
     * @returns {number|string}        Milliseconds (when parsing) or a formatted string.
     * @throws {Error}                If `val` is neither a non‑empty string nor a finite number.
     */
    module.exports = function (val, options) {
      options = options || {};
      const type = typeof val;

      // Parse a string like "2h", "1.5 days", etc.
      if (type === "string" && val.length > 0) {
        return parse(val);
      }

      // Format a number of milliseconds.
      if (type === "number" && isFinite(val)) {
        return options.long ? fmtLong(val) : fmtShort(val);
      }

      // Anything else is an error.
      throw new Error(
        "val is not a non-empty string or a valid number. val=" +
          JSON.stringify(val)
      );
    };

    // -----------------------------------------------------------------
    // Helper: parse a human‑readable time string into milliseconds.
    // -----------------------------------------------------------------
    function parse(str) {
      str = String(str);
      // Guard against absurdly long inputs (the original library does this).
      if (str.length > 100) return;

      const match = /^(-?(?:\d+)?\.?\d+) *(milliseconds?|msecs?|ms|seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|h|days?|d|weeks?|w|years?|yrs?|y)?$/i.exec(
        str
      );
      if (!match) return;

      const n = parseFloat(match[1]);
      const unit = (match[2] || "ms").toLowerCase();

      switch (unit) {
        case "years":
        case "year":
        case "yrs":
        case "yr":
        case "y":
          return n * YEAR;
        case "weeks":
        case "week":
        case "w":
          return n * WEEK;
        case "days":
        case "day":
        case "d":
          return n * DAY;
        case "hours":
        case "hour":
        case "hrs":
        case "hr":
        case "h":
          return n * HOUR;
        case "minutes":
        case "minute":
        case "mins":
        case "min":
        case "m":
          return n * MINUTE;
        case "seconds":
        case "second":
        case "secs":
        case "sec":
        case "s":
          return n * SECOND;
        case "milliseconds":
        case "millisecond":
        case "msecs":
        case "msec":
        case "ms":
          return n;
        default:
          return undefined;
      }
    }

    // -----------------------------------------------------------------
    // Helper: short format (e.g. "2h", "5d")
    // -----------------------------------------------------------------
    function fmtShort(ms) {
      const abs = Math.abs(ms);
      if (abs >= DAY) return Math.round(ms / DAY) + "d";
      if (abs >= HOUR) return Math.round(ms / HOUR) + "h";
      if (abs >= MINUTE) return Math.round(ms / MINUTE) + "m";
      if (abs >= SECOND) return Math.round(ms / SECOND) + "s";
      return ms + "ms";
    }

    // -----------------------------------------------------------------
    // Helper: long format (e.g. "2 hours", "5 days")
    // -----------------------------------------------------------------
    function fmtLong(ms) {
      const abs = Math.abs(ms);
      if (abs >= DAY) return plural(ms, abs, DAY, "day");
      if (abs >= HOUR) return plural(ms, abs, HOUR, "hour");
      if (abs >= MINUTE) return plural(ms, abs, MINUTE, "minute");
      if (abs >= SECOND) return plural(ms, abs, SECOND, "second");
      return ms + " ms";
    }

    // -----------------------------------------------------------------
    // Helper: pluralise a unit name when appropriate.
    // -----------------------------------------------------------------
    function plural(ms, abs, unitMs, name) {
      const isPlural = abs >= unitMs * 1.5;
      return Math.round(ms / unitMs) + " " + name + (isPlural ? "s" : "");
    }
  },
});

/**
 * Export the `ms` function directly, mirroring the original bundle's behaviour:
 * the IIFE evaluated to the result of `requireMs()`.
 */
module.exports = requireMs();

