    "use strict";

    // Characters that need escaping and their HTML entities.
    const RE = /["'&<>]/;

    /** Escape a string for safe insertion into HTML. */
    function escapeHtml(input) {
      const str = "" + input;               // coerce to string
      const firstMatch = RE.exec(str);
      if (!firstMatch) return str;          // fast path – nothing to escape

      let result = "";
      let last = 0;

      // Start scanning from the first matched character.
      for (let i = firstMatch.index; i < str.length; i++) {
        let replacement;
        switch (str.charCodeAt(i)) {
          case 34: // "
            replacement = "&quot;";
            break;
          case 38: // &
            replacement = "&amp;";
            break;
          case 39: // '
            replacement = "&#39;";
            break;
          case 60: // <
            replacement = "&lt;";
            break;
          case 62: // >
            replacement = "&gt;";
            break;
          default:
            continue; // character does not need escaping
