"use strict";

/**
 * Minimal implementation of the `kleur` library.
 *
 * This file is a cleaned‑up version of the original source found in
 * `benchmarks/reconstruct/.cache/kleur/index.js`.  It provides a set of
 * functions that wrap text in ANSI escape codes for colour and style
 * output in terminals.
 *
 * The implementation respects the following environment variables:
 *
 * - `FORCE_COLOR` – forces colour output when set to a non‑zero value.
 * - `NODE_DISABLE_COLORS` – disables colour output when defined.
 * - `NO_COLOR` – disables colour output when defined.
 * - `TERM` – disables colour when equal to `"dumb"`.
 *
 * Colour output is also disabled when the process is not attached to a TTY
 * unless `FORCE_COLOR` forces it.
 */

let FORCE_COLOR;
let NODE_DISABLE_COLORS;
let NO_COLOR;
let TERM;
let isTTY = true;

// Detect environment (Node.js) and read relevant variables.
if (typeof process !== "undefined") {
  ({ FORCE_COLOR, NODE_DISABLE_COLORS, NO_COLOR, TERM } = process.env || {});
  isTTY = !!(process.stdout && process.stdout.isTTY);
}

/**
 * Core object exposing colour/style helpers.
 *
 * The `enabled` flag determines whether ANSI codes are actually emitted.
 */
const $ = {
  enabled:
    !NODE_DISABLE_COLORS &&
    NO_COLOR == null &&
    TERM !== "dumb" &&
    (FORCE_COLOR != null && FORCE_COLOR !== "0" || isTTY),

  // modifiers
  reset: init(0, 0),
  bold: init(1, 22),
  dim: init(2, 22),
  italic: init(3, 23),
  underline: init(4, 24),
  inverse: init(7, 27),
  hidden: init(8, 28),
  strikethrough: init(9, 29),

  // foreground colours
  black: init(30, 39),
  red: init(31, 39),
  green: init(32, 39),
  yellow: init(33, 39),
  blue: init(34, 39),
  magenta: init(35, 39),
  cyan: init(36, 39),
  white: init(37, 39),
  gray: init(90, 39),
  grey: init(90, 39),

  // background colours
  bgBlack: init(40, 49),
  bgRed: init(41, 49),
  bgGreen: init(42, 49),
  bgYellow: init(43, 49),
  bgBlue: init(44, 49),
  bgMagenta: init(45, 49),
  bgCyan: init(46, 49),
  bgWhite: init(47, 49)
};

/**
 * Apply a list of ANSI blocks to a string, handling nested resets.
 *
 * @param {Array<{open:string,close:string,rgx:RegExp}>} arr   List of blocks.
 * @param {string} str                                         Input text.
 * @returns {string}                                           Styled text.
 */
function run(arr, str) {
  let beg = "";
  let end = "";

  for (let i = 0; i < arr.length; i++) {
    const blk = arr[i];
    beg += blk.open;
    end += blk.close;

    // If the closing sequence already appears inside the string we need to
    // re‑order it so that nesting works correctly.
    if (str.indexOf(blk.close) !== -1) {
      str = str.replace(blk.rgx, blk.close + blk.open);
    }
  }

  return beg + str + end;
}

/**
 * Create a chainable context that remembers which codes have already been
 * applied.  This enables calls such as `kleur.red.bold('text')`.
 *
 * @param {Array<number>} has   List of opening codes already used.
 * @param {Array<Object>} keys  Corresponding block objects.
 * @returns {Object}            Context with bound colour functions.
 */
function chain(has, keys) {
  const ctx = { has, keys };

  // Bind every colour / style function to the new context.
  ctx.reset = $.reset.bind(ctx);
  ctx.bold = $.bold.bind(ctx);
  ctx.dim = $.dim.bind(ctx);
  ctx.italic = $.italic.bind(ctx);
  ctx.underline = $.underline.bind(ctx);
  ctx.inverse = $.inverse.bind(ctx);
  ctx.hidden = $.hidden.bind(ctx);
  ctx.strikethrough = $.strikethrough.bind(ctx);
  ctx.black = $.black.bind(ctx);
  ctx.red = $.red.bind(ctx);
  ctx.green = $.green.bind(ctx);
  ctx.yellow = $.yellow.bind(ctx);
  ctx.blue = $.blue.bind(ctx);
  ctx.magenta = $.magenta.bind(ctx);
  ctx.cyan = $.cyan.bind(ctx);
  ctx.white = $.white.bind(ctx);
  ctx.gray = $.gray.bind(ctx);
  ctx.grey = $.grey.bind(ctx);
  ctx.bgBlack = $.bgBlack.bind(ctx);
  ctx.bgRed = $.bgRed.bind(ctx);
  ctx.bgGreen = $.bgGreen.bind(ctx);
  ctx.bgYellow = $.bgYellow.bind(ctx);
  ctx.bgBlue = $.bgBlue.bind(ctx);
  ctx.bgMagenta = $.bgMagenta.bind(ctx);
  ctx.bgCyan = $.bgCyan.bind(ctx);
  ctx.bgWhite = $.bgWhite.bind(ctx);

  return ctx;
}

/**
 * Factory that creates a colour/style function.
 *
 * @param {number} open   ANSI opening code.
 * @param {number} close  ANSI closing code.
 * @returns {function(string=):any}  The generated function.
 *
 * The returned function works in two modes:
 *
 * 1. **Standalone** – called directly, e.g. `red('text')`.  It returns the
 *    coloured string (or a chainable context when called without arguments).
 *
 * 2. **Chained** – when the function is invoked as a method of a context
 *    created by a previous call, it adds its code to the context and returns
 *    either the context (if no text is supplied) or the coloured string.
 */
function init(open, close) {
  const blk = {
    open: `\x1B[${open}m`,
    close: `\x1B[${close}m`,
    rgx: new RegExp(`\\x1b\\[${close}m`, "g")
  };

  return function (txt) {
    // `this` is a context object when the function is used in a chain.
    if (this !== undefined && this.has !== undefined) {
      // Record the code only once per chain.
      if (!this.has.includes(open)) {
        this.has.push(open);
        this.keys.push(blk);
      }

      // No argument → return the context for further chaining.
      if (txt === undefined) {
        return this;
      }

      // With argument → apply accumulated codes.
      return $.enabled ? run(this.keys, String(txt)) : String(txt);
    }

    // Not called as a method → behave as a top‑level helper.
    if (txt === undefined) {
      // Return a fresh chain containing only this code.
      return chain([open], [blk]);
    }

    return $.enabled ? run([blk], String(txt)) : String(txt);
  };
}

// Export the colour helper object.
module.exports = $;
